#!/usr/bin/env python3
"""Builds silvermere-mapper.xml (a Mudlet package) from silvermere-mapper.lua.

    python3 tools/mudlet/build.py          # writes the package
    python3 tools/mudlet/build.py --check  # fails if the package is out of date
"""

import sys
from pathlib import Path
from xml.sax.saxutils import escape

HERE = Path(__file__).resolve().parent
LUA = HERE / "silvermere-mapper.lua"
XML = HERE / "silvermere-mapper.xml"

TEMPLATE = """<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE MudletPackage>
<!-- Generated by tools/mudlet/build.py from silvermere-mapper.lua: edit that, then run it. -->
<MudletPackage version="1.001">
	<ScriptPackage>
		<Script isActive="yes" isFolder="no">
			<name>Silvermere mapper</name>
			<packageName>silvermere-mapper</packageName>
			<script>{script}</script>
			<eventHandlerList />
		</Script>
	</ScriptPackage>
</MudletPackage>
"""


def build() -> str:
    return TEMPLATE.format(script=escape(LUA.read_text(encoding="utf-8")))


def main() -> int:
    text = build()
    if "--check" in sys.argv[1:]:
        if not XML.exists() or XML.read_text(encoding="utf-8") != text:
            print(f"{XML.name} is out of date: run python3 tools/mudlet/build.py", file=sys.stderr)
            return 1
        return 0
    XML.write_text(text, encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main())
